                    let webdav_entry = OpendalDirEntry::new(dav_stream.op.clone(), entry);
                    return Ready(Some(Ok(Box::new(webdav_entry) as Box<dyn DavDirEntry>)));
                }
                None => return Ready(None),
            }
        }
    }
}

